from lib import *
S = SS('p11')
steps = [
    step("先说明方法:我在进程里包了一层 socket.getaddrinfo,统计被调用的次数,并给 *.test 主机名加 100 ms 的 sleep 来模拟慢 DNS(延迟是模拟的,调用次数是真实的)。requests/urllib3 自己不缓存 DNS:20 次 requests.get(每次新连接)调用了 20 次 getaddrinfo,共 2091 ms;一个 Session 发 20 次、复用同一条连接,只调用 1 次,114 ms;同一个 Session 但每次带 Connection: close 逼着新建连接,又是 20 次,2094 ms。DNS 的代价跟着“新建连接”走。", t=tl(S(1)), done=lidx(S(1), '一个 Session 发 20 次(复用 1 条连接)'), mark=lidx(S(1), '20 次 requests.get', 'Connection: close:'), b=bars([['requests.get ×20:getaddrinfo 次数', 20, '20'], ['Session ×20:getaddrinfo 次数', 1, '1'], ['Session + close ×20:次数', 20, '20']], 20, mark=[0, 2], done=[1]), kv=KV([['requests.get ×20', '20 次解析,2091 ms'], ['Session ×20', '1 次解析,114 ms'], ['每次新连接', '都要解析']], ['每次新连接'])),
    step("aiohttp 的 TCPConnector 自带 DNS 缓存,默认 use_dns_cache=True、ttl_dns_cache=10(秒)。force_close=True 让 20 个请求都新建连接:默认只调用 1 次 getaddrinfo,请求累计约 120 ms;use_dns_cache=False 调用 20 次,约 2099 ms。ttl_dns_cache=1 且每次请求后等 0.4 秒:10 个新连接调用了 4 次——缓存到期后重新解析,累计约 433 ms。", t=tl(S(2)), done=lidx(S(2), '默认(缓存开)'), mark=lidx(S(2), 'use_dns_cache=False', 'ttl_dns_cache=1,'), b=bars([['默认缓存:getaddrinfo 次数', 1, '1'], ['use_dns_cache=False:次数', 20, '20'], ['ttl=1 秒:次数(10 个连接)', 4, '4']], 20, done=[0], mark=[1]), kv=KV([['默认', 'use_dns_cache=True,ttl 10 秒'], ['关缓存', '每个新连接解析一次'], ['ttl=1', '到期后重新解析']], ['默认'])),
    step("getaddrinfo 是阻塞调用,aiohttp 把它放进线程池,所以并发解析数被线程池卡住。100 个不同主机名、每次解析模拟 200 ms:默认线程池里同时在解析的峰值只有 14(这台机器 os.cpu_count()=10,与 min(32, cpu+4)=14 相符),100 个请求全部完成要 1625 ms(约 8 批 × 200 ms);换成 100 个线程的线程池,峰值 100,232 ms 完成。DNS 慢又同时抓很多个不同域名时,瓶颈会落在这个线程池上。", t=tl(S(3)), done=lidx(S(3), '换成 100 个线程'), mark=lidx(S(3), '默认线程池:'), b=bars([['默认线程池:并发解析峰值', 14, '14'], ['100 线程池:并发解析峰值', 100, '100'], ['默认线程池:完成 ms', 1625, '1625'], ['100 线程池:完成 ms', 232, '232']], 1625, mark=[2], done=[3]), kv=KV([['默认线程池', '峰值 14,1625 ms'], ['100 线程池', '峰值 100,232 ms'], ['瓶颈', '解析的线程池大小']], ['瓶颈'])),
    step("localhost 会解析出两个地址,顺序是 ::1 然后 127.0.0.1。服务器只听 IPv4 时,每次新连接的开销:localhost 平均 0.92 ms,127.0.0.1 平均 0.71 ms,多约 0.21 ms。拆开测:getaddrinfo(\"localhost\") 每次 0.121 ms,getaddrinfo(\"127.0.0.1\") 只要 0.002 ms;对 ::1 发起连接被拒绝每次 0.041 ms。多出的时间大部分是解析名字(0.121),少部分是先被拒绝的 ::1 尝试(0.041),两者加起来与总差值接近。", t=tl(S(4)), done=lidx(S(4), '拆开测'), mark=lidx(S(4), '200 次新连接', 'getaddrinfo("localhost") 的顺序'), b=bars([['localhost 每次请求 ms', 0.92, '0.92'], ['127.0.0.1 每次请求 ms', 0.71, '0.71'], ['解析 localhost ms', 0.121, '0.121'], ['被拒绝的 ::1 ms', 0.041, '0.041']], 1, mark=[0], done=[1]), kv=KV([['地址顺序', '::1 先,127.0.0.1 后'], ['多出的时间', '解析 0.121 + ::1 被拒 0.041'], ['直接用 IP', '省掉这两项']], ['多出的时间'])),
]
A = mkartp('p11', 11, '爬虫,DNS,getaddrinfo,requests,aiohttp,线程池,localhost,Python,真实验证,动画演示',
    '用包装过的 getaddrinfo 统计爬虫库的 DNS 行为:requests 每建一条新连接解析一次(20 次 requests.get 解析 20 次,Session 复用只解析 1 次);aiohttp 默认缓存 10 秒,关掉后同样 20 次;并发解析被默认线程池的 14 个线程卡住(100 个主机名 1625 ms,换 100 线程 232 ms);localhost 比 127.0.0.1 每次多约 0.21 ms。',
    '爬虫碰到的 DNS 问题往往不是“解析失败”,而是“慢”和“被重复做”。这篇在本机用一个包装过的 getaddrinfo 看清:requests 和 aiohttp 各自什么时候解析、缓存多久、并发解析会被什么限制,以及 localhost 为什么比 127.0.0.1 慢一点。',
    [('20 对 1', '20 个请求的 getaddrinfo 调用次数:每次新建连接对复用同一个 Session 的连接'), ('14 / 100', '100 个不同主机名同时解析时,默认线程池的并发峰值对换成 100 线程池后的峰值'), ('0.21 ms', 'localhost 比 127.0.0.1 每次新连接多花的时间')],
    [('requests:DNS 跟着新连接走', '<p>urllib3 每建一条新连接就调用一次 <code>getaddrinfo</code>,自己不缓存(本机操作系统可能有缓存,这里看不到)。所以 Session 的连接复用同时也省掉了 DNS;而每次 <code>Connection: close</code> 或每次 <code>requests.get</code>,都会重新解析。上面的 100 ms 延迟是我模拟的,真实的解析耗时取决于你的 DNS 服务器。</p>'),
     ('aiohttp:自带缓存', '<p><code>TCPConnector</code> 默认缓存解析结果 10 秒(<code>use_dns_cache=True</code>,<code>ttl_dns_cache=10</code>)。同一个主机的 20 个新连接只解析了一次;关掉缓存就是 20 次;把有效期调成 1 秒,10 个相隔 0.4 秒的连接解析了 4 次。</p>'),
     ('解析被线程池卡住', '<p>aiohttp 默认用 <code>getaddrinfo</code>,在 asyncio 的默认线程池里执行。实测同时在解析的数量峰值是 14,与 <code>min(32, cpu+4)</code> 的结果一致。解析慢(这里模拟 200 ms)又要抓大量不同域名时,100 个请求被分成约 8 批,用了 1625 ms;换成更大的线程池后 232 ms。另一种办法是使用异步 DNS 库,我没有安装和测试。</p>'),
     ('localhost 的额外开销', '<p><code>localhost</code> 解析出 <code>::1</code> 和 <code>127.0.0.1</code>,<code>::1</code> 在前。服务器只听 IPv4 时,客户端先试 <code>::1</code> 被拒绝,再连 IPv4。每次新连接比直接用 <code>127.0.0.1</code> 多约 0.21 ms,其中解析名字 0.121 ms,被拒绝的 <code>::1</code> 尝试 0.041 ms(两项相加约 0.16 ms,剩下的差额没有再拆)。差距很小,但在本机压测时别把它算进服务器耗时。</p>')],
    steps,
    [ENV_P + '。把 socket.getaddrinfo 换成包装函数:只对 *.test 主机名计数、按需 time.sleep 模拟 DNS 延迟(延迟是模拟的)、统计并发峰值,并全部解析到 127.0.0.1;aiohttp 的 force_close=True 让每个请求新建连接;线程池大小公式 min(32, cpu+4) 是从观察到的峰值 14 反推吻合,没有重新读文档;localhost 对比交替跑 5 轮,每轮 200 次新连接',
     '没有验证:真实 DNS 服务器的耗时与超时、失败重试;操作系统层面的 DNS 缓存;aiodns/c-ares 等异步 DNS 解析器;IPv6 优先的 Happy Eyeballs 并行连接(aiohttp 有这个选项,没测);DNS 记录的 TTL 与 aiohttp ttl_dns_cache 的关系;DNS 轮询(多个 A 记录)下的连接选择(后面有专门的文章)'],
    'DNS 解析')
